function isValidSudoku(board: string[][]): boolean {
  // По одному набору увиденных цифр на каждую строку, столбец и блок 3x3
  const rows = Array.from({ length: 9 }, () => new Set<string>());
  const cols = Array.from({ length: 9 }, () => new Set<string>());
  const boxes = Array.from({ length: 9 }, () => new Set<string>());

  for (let r = 0; r < 9; r++) {
    for (let c = 0; c < 9; c++) {
      const d = board[r][c];
      // Пустые клетки не проверяем
      if (d === '.') continue;

      // Номер блока: 3 блока в ряду, блоки нумеруются слева направо, сверху вниз
      const b = Math.floor(r / 3) * 3 + Math.floor(c / 3);

      // Цифра уже встречалась в этой строке, столбце или блоке — доска некорректна
      if (rows[r].has(d) || cols[c].has(d) || boxes[b].has(d)) {
        return false;
      }

      rows[r].add(d);
      cols[c].add(d);
      boxes[b].add(d);
    }
  }

  return true;
}

// Время: O(81) = O(1) — доска фиксированного размера (в общем виде O(n²))
// Память: O(81) = O(1)
